const scenarioFrames=[['a school portal is adding a new feature','support learners who use small screens and keyboards'],['an online shop is fixing a checkout flow','avoid invalid state when a visitor changes a selection'],['a booking service is receiving incomplete data','handle missing and unexpected values without breaking the task'],['a community site is adding a public form','make validation understandable and accessible'],['a dashboard is growing from ten records to thousands','keep the solution maintainable as data volume grows'],['a mobile user reports a bug that desktop testing missed','reproduce the issue at the relevant viewport and boundary'],['a team is refactoring a legacy module','preserve existing behavior while isolating the change'],['a third-party API begins returning delayed responses','represent waiting, success, and failure states'],['a user submits the same action twice','prevent duplicate work and keep state consistent'],['a colleague cannot understand a complicated implementation','make intent explicit and test public behavior'],['a page is being used with assistive technology','preserve semantics, focus order, and useful feedback'],['a service must work on a slow connection','avoid unnecessary work and handle latency gracefully'],['a report contains empty or malformed fields','validate input and explain what cannot be processed'],['a new feature must coexist with existing components','make a narrow change at the correct responsibility boundary'],['a production issue appears only with unusual input','add a focused regression test before applying a fix'],['a team is preparing a release','check normal behavior, failure paths, configuration, and diagnostics'],['a record must be updated without losing related data','preserve invariants and update related state consistently'],['an application is becoming difficult to debug','improve observability and narrow the failure to a reproducible case'],['a stakeholder requests a quick workaround','choose the smallest correct fix instead of hiding the symptom'],['a public endpoint receives untrusted input','validate at the trust boundary and never trust raw input'],['a multilingual interface is being introduced','keep meaning and data handling stable across locales'],['a feature must be usable by new team members','document the contract and keep the implementation idiomatic'],['a cached response can become stale','define when data refreshes and how stale states are handled'],['two operations may run at the same time','avoid races and make ordering or cancellation explicit'],['an imported dataset changes format','check the incoming schema and report incompatible fields'],['a developer is choosing between two implementations','compare correctness, maintainability, and test evidence'],['a customer reports intermittent behavior','capture useful context and test more than the happy path'],['a system must remain reliable after future updates','separate concerns and test the public contract'],['a large feature must be delivered in stages','define small increments with testable acceptance criteria'],['a security review finds a risky shortcut','remove the underlying risk and verify the protection']];
