function codeExample(course,topic){const examples={html:'<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>Accessible example</title>\n</head>\n<body>\n  <main>\n    <h1>'+topic.title+'</h1>\n    <p>'+topic.objective+'</p>\n  </main>\n</body>\n</html>',css:'.component {\n  max-width: 68rem;\n  margin-inline: auto;\n  padding: clamp(1rem, 3vw, 2rem);\n}\n.component:focus-visible { outline: 3px solid currentColor; outline-offset: 3px; }',javascript:'function applyRule(input) {\n  if (input == null) throw new TypeError("Expected a value");\n  return String(input).trim();\n}\n\ntry {\n  console.log(applyRule(" example "));\n} catch (error) {\n  console.error("Unable to process input", error);\n}',python:'def apply_rule(value):\n    if value is None:\n        raise ValueError("A value is required")\n    return str(value).strip()\n\nif __name__ == "__main__":\n    print(apply_rule(" example "))',react:'function TopicPanel({ title, description }) {\n  return (\n    <section aria-labelledby="topic-title">\n      <h2 id="topic-title">{title}</h2>\n      <p>{description}</p>\n    </section>\n  );\n}',sql:'-- Bind external values using your database driver’s parameter syntax.\nSELECT item_id, status\nFROM work_items\nWHERE status = :status\nORDER BY updated_at DESC;',typescript:'type InputState = { kind: "ready"; value: string } | { kind: "missing" };\nfunction applyRule(input: InputState): string {\n  if (input.kind === "missing") return "No value supplied";\n  return input.value.trim();\n}'};const other={java:'final class TopicService {\n    String applyRule(String input) {\n        if (input == null) throw new IllegalArgumentException("input required");\n        return input.trim();\n    }\n}',c:'int apply_rule(int value) { /* validate assumptions */ return value; }',cplusplus:'#include <string>\n#include <utility>\nclass TopicValue {\npublic:\n explicit TopicValue(std::string value): value_(std::move(value)) {}\n const std::string& value() const noexcept { return value_; }\nprivate: std::string value_;\n};',csharp:'static string ApplyRule(string input) {\n    ArgumentNullException.ThrowIfNull(input);\n    return input.Trim();\n}',php:'function applyRule(string $input): string { return trim($input); }\n$value = applyRule(" example ");',go:'func applyRule(input string) (string, error) {\n if input == "" { return "", errors.New("input required") }\n return strings.TrimSpace(input), nil\n}',rust:'fn apply_rule(input: Option<&str>) -> Result<String, &\'static str> {\n let value = input.ok_or("input required")?;\n Ok(value.trim().to_owned())\n}',kotlin:'fun applyRule(input: String?): String {\n requireNotNull(input) { "input required" }; return input.trim()\n}',swift:'func applyRule(_ input: String?) throws -> String {\n guard let input else { throw InputError.missing }; return input.trimmingCharacters(in: .whitespacesAndNewlines)\n}',dart:'String applyRule(String? input) {\n if (input == null) throw ArgumentError.notNull("input"); return input.trim();\n}',ruby:'def apply_rule(input)\n  raise ArgumentError, "input required" if input.nil?\n  input.to_s.strip\nend',r:'apply_rule <- function(input) {\n if (is.null(input) || length(input) == 0) stop("input required")\n trimws(as.character(input))\n}',lua:'local function apply_rule(input)\n assert(input ~= nil, "input required")\n return tostring(input):match("^%s*(.-)%s*$")\nend'};return examples[course.id]||other[course.id]||('// '+course.label+' example\n// Validate the input, apply '+topic.title+', and test expected plus edge cases.\n')}
